const html = `<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>태풍 경로 탐구</title><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><style>*{box-sizing:border-box}body{margin:0;background:#f2f5f4;color:#152c2d;font-family:system-ui,sans-serif}header{padding:23px 5%;background:#123c3c;color:white;display:flex;justify-content:space-between;align-items:center}header small{color:#a9d2cb}main{max-width:1400px;margin:auto;padding:32px 5%}h1{font-size:32px;margin:10px 0}p{color:#617675;line-height:1.6}.layout{display:grid;grid-template-columns:340px 1fr;gap:20px}.panel{background:white;border:1px solid #e0e9e5;border-radius:16px;padding:22px;box-shadow:0 8px 25px #183b3210}label{display:block;font-size:13px;font-weight:700;margin:18px 0 7px}input,select,button{font:inherit;border:1px solid #cfddda;border-radius:8px;padding:11px;width:100%;background:white}button{cursor:pointer;background:#146e5d;color:white;border:0;font-weight:700;margin-top:12px}button.secondary{background:#edf5f2;color:#146e5d}button:disabled{opacity:.5;cursor:default}#map{height:510px;border-radius:12px;background:#e3eeeb}.row{display:flex;gap:8px}.row>*{flex:1}.status{font-size:13px;color:#6c7772;white-space:pre-wrap}.date{font-size:22px;font-weight:800;color:#146e5d;margin:18px 0 4px}input[type=range]{padding:0;accent-color:#16836c}.note{font-size:12px}.badge{font-size:12px;background:#dbeee7;color:#145a4f;padding:6px 10px;border-radius:20px}.leaflet-container{font-family:inherit}@media(max-width:760px){.layout{grid-template-columns:1fr}#map{height:400px}main{padding:22px 4%}header{padding:18px 4%}}</style><header><strong>◉ 태풍 경로 탐구</strong><small>WEATHER DATA LAB</small></header><main><span class="badge">2020 — 2025 · 기상청 자료</span><h1>태풍은 어디를 지나갔을까?</h1><p>태풍의 이동을 날짜에 따라 따라가 보세요. 한반도 주변 경로를 직접 살펴볼 수 있습니다.</p><div class="layout"><section class="panel"><strong>경로 선택</strong><label for="key">기상청 API 인증키</label><input id="key" type="password" autocomplete="off" placeholder="인증키 입력"><p class="note">키는 브라우저에 저장하지 않으며 기상청 조회에만 사용합니다.</p><label for="year">태풍 발생 연도</label><select id="year"><option>2025</option><option>2024</option><option>2023</option><option>2022</option><option>2021</option><option>2020</option></select><button id="load">태풍 목록 불러오기</button><label for="storm">태풍</label><select id="storm"><option value="">먼저 목록을 불러오세요</option></select><button id="track" disabled>경로 보기</button><p class="status" id="status">기상청 API 인증키를 입력하고 목록을 불러오세요.</p><hr style="border:0;border-top:1px solid #e5eeea;margin:22px 0"><strong>시간 여행</strong><div class="date" id="date">날짜를 선택하세요</div><p class="note" id="detail">경로의 점을 눌러도 확인할 수 있어요.</p><input id="slider" type="range" min="0" max="0" value="0" disabled aria-label="태풍 경로 시각"><div class="row"><button class="secondary" id="play" disabled>▶ 재생</button><button class="secondary" id="reset" disabled>↺ 처음</button></div><p class="note">관측 시각은 UTC를 한국시간(KST)으로 변환합니다. 이 지도는 교육용이며 재난 대응에 사용하지 마세요.</p></section><section class="panel"><div id="map"></div><p class="note">● 태풍 중심 위치　— 기상청 분석 경로　· · · 예상 경로가 아닌 발표된 분석 자료입니다. 대한민국 통과 여부는 경로를 확대해 확인하세요.</p></section></div></main><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
const $=id=>document.getElementById(id);let points=[],markers=[],path,timer=null;let map=L.map('map').setView([31,131],4);L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',{attribution:'&copy; OpenStreetMap contributors &copy; CARTO',maxZoom:18}).addTo(map);
function parse(text,needed){let lines=text.split(/\\r?\\n/);let headers=null;for(let line of lines){let s=line.trim().replace(/^#+\\s*/, '');let fields=(s.includes(',')?s.split(','):s.split(/\\s+/)).map(x=>x.trim().replace(/-+$/,'' )).filter(x=>x && x!=='(UTC)');if(needed.every(n=>fields.includes(n))){headers=fields;continue}if(headers&&!line.trim().startsWith('#')&&line.trim()){let values=line.includes(',')?line.split(',').map(x=>x.trim()):line.trim().split(/\\s+/);if(values.length>=headers.length){let obj={};headers.forEach((h,i)=>obj[h]=values[i]);(parse.rows||(parse.rows=[])).push(obj)}}}let rows=parse.rows||[];parse.rows=[];return rows}
async function api(kind,extra){let key=$('key').value.trim();if(!key)throw Error('인증키를 입력해 주세요.');let r=await fetch('/api/'+kind,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({key,year:$('year').value,...extra})});let t=await r.text();if(!r.ok)throw Error(t);return t}
$('load').onclick=async()=>{try{$('status').textContent='태풍 목록을 불러오는 중입니다…';let t=await api('list',{});let rows=parse(t,['YY','SEQ']);let s=$('storm');s.replaceChildren(new Option('태풍을 선택하세요',''));for(let x of rows){let n=Number(x.SEQ);if(Number.isInteger(n)&&n>0)s.add(new Option(n+'호 '+(x.TYP_NAME||x.TYP_EN||''),n))}if(s.options.length===1)throw Error('목록을 읽지 못했습니다. API 활용신청 또는 해당 연도 자료를 확인해 주세요.');$('track').disabled=false;$('status').textContent=s.options.length-1+'개 태풍을 불러왔습니다. 태풍을 선택해 주세요.'}catch(e){$('status').textContent=e.message}};
function fmt(s){s=String(s||'');let m=s.match(/^(\\d{4})(\\d{2})(\\d{2})(\\d{2})(\\d{2})?/);if(!m)return s||'시각 정보 없음';let d=new Date(Date.UTC(+m[1],+m[2]-1,+m[3],+m[4],+(m[5]||0)));return new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)+' KST'}
function show(i){if(!points.length)return;i=Math.min(points.length-1,Math.max(0,i));$('slider').value=i;let p=points[i];$('date').textContent=fmt(p.FT_TM||p.TYP_TM);$('detail').textContent='위도 '+p.lat.toFixed(1)+'° · 경도 '+p.lon.toFixed(1)+'°'+(p.PS?' · 중심기압 '+p.PS+' hPa':'');markers.forEach((m,j)=>m.setStyle({fillOpacity:j===i?1:.55,radius:j===i?8:4}));if(path)map.removeLayer(path);path=L.polyline(points.slice(0,i+1).map(p=>[p.lat,p.lon]),{color:'#e47752',weight:4}).addTo(map)}
$('track').onclick=async()=>{try{if(!$('storm').value)throw Error('태풍을 선택해 주세요.');clearInterval(timer);$('play').textContent='▶ 재생';$('status').textContent='경로를 불러오는 중입니다…';let t=await api('track',{typ:$('storm').value});let rows=parse(t,['LAT','LON']);points=rows.filter(p=>String(p.FT||'0')==='0').map(p=>({...p,lat:Number(p.LAT),lon:Number(p.LON)})).filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon)&&p.lat>=-90&&p.lat<=90&&p.lon>=-180&&p.lon<=180);points.sort((a,b)=>String(a.FT_TM||a.TYP_TM).localeCompare(String(b.FT_TM||b.TYP_TM)));if(!points.length)throw Error('이 태풍의 분석 경로가 없거나 응답을 읽지 못했습니다. API 활용신청과 자료 제공 범위를 확인해 주세요.');markers.forEach(m=>map.removeLayer(m));markers=points.map((p,i)=>L.circleMarker([p.lat,p.lon],{radius:4,color:'#b9573d',fillColor:'#e47752',fillOpacity:.6,weight:1}).addTo(map).on('click',()=>show(i)));$('slider').max=points.length-1;$('slider').disabled=false;$('play').disabled=false;$('reset').disabled=false;map.fitBounds(L.latLngBounds(points.map(p=>[p.lat,p.lon])),{padding:[35,35],maxZoom:7});show(0);$('status').textContent='분석 지점 '+points.length+'개 · 점 또는 재생 버튼을 눌러 보세요.'}catch(e){$('status').textContent=e.message}};
$('slider').oninput=e=>show(+e.target.value);$('reset').onclick=()=>{clearInterval(timer);timer=null;$('play').textContent='▶ 재생';show(0)};$('play').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('play').textContent='▶ 재생';return}if(+$('slider').value>=points.length-1)show(0);$('play').textContent='❚❚ 일시정지';timer=setInterval(()=>{let i=+$('slider').value+1;if(i>=points.length){clearInterval(timer);timer=null;$('play').textContent='▶ 재생';return}show(i)},650)};
</script></html>`;
export default {async fetch(req){let u=new URL(req.url);if(u.pathname==='/')return new Response(html,{headers:{'content-type':'text/html;charset=utf-8'}});if(req.method!=='POST'||!['/api/list','/api/track'].includes(u.pathname))return new Response('Not found',{status:404});try{let x=await req.json();if(!/^20(20|21|22|23|24|25)$/.test(String(x.year))||!x.key||String(x.key).length>100)return new Response('연도와 인증키를 확인해 주세요.',{status:400});let params=new URLSearchParams({YY:x.year,disp:'1',help:'0',authKey:x.key});if(u.pathname==='/api/track'){if(!/^\d{1,2}$/.test(String(x.typ)))return new Response('태풍 번호를 확인해 주세요.',{status:400});params.set('typ',x.typ);params.set('mode','0')}let endpoint=u.pathname==='/api/list'?'typ_lst.php':'typ_data.php';let res=await fetch('https://apihub.kma.go.kr/api/typ01/url/'+endpoint+'?'+params);if(!res.ok)return new Response('기상청 API 요청에 실패했습니다. ('+res.status+')',{status:502});let body=await res.text();return new Response(body,{headers:{'content-type':'text/plain;charset=utf-8','cache-control':'no-store'}})}catch(e){return new Response('기상청 자료를 불러오지 못했습니다.',{status:502})}}};

